def compute(vars):
    net_tangible_assets = vars["v1"]
    estimated_purchase_price = vars["v2"]

    if estimated_purchase_price == 0:
        return None

    portion = net_tangible_assets / estimated_purchase_price

    return {
        "value": portion,
        "trace": {
            "net_tangible_assets": net_tangible_assets,
            "estimated_purchase_price": estimated_purchase_price,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
